package com.mo.economy_system.common.transfer;import static org.junit.jupiter.api.Assertions.*;import com.mo.economy_system.common.check.ClientFileCheckType;import java.security.MessageDigest;import java.util.*;import org.junit.jupiter.api.Test;
class CheckedFileTransferStoreTest{private static String hash(byte[] b)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}@Test void streamsInOrderWithoutAccumulator()throws Exception{byte[] bytes=new byte[18001];Arrays.fill(bytes,(byte)7);var store=new CheckedFileTransferStore();UUID t=UUID.randomUUID(),r=UUID.randomUUID(),id=UUID.randomUUID();var key=new CheckedFileTransferStore.Key(t,r,ClientFileCheckType.MODS,"a.jar");var p=new CheckedFileTransferStore.Pending(key,"target","requester",bytes.length,hash(bytes),1,100);assertEquals(CheckedFileTransferStore.Result.CREATED,store.create(p,1));assertEquals(CheckedFileTransferStore.Result.READY,store.ready(key,t,CheckedFileTransferControl.ready(id,bytes.length,hash(bytes)),2));assertEquals(CheckedFileTransferStore.Result.FORWARD,store.chunk(key,t,id,0,2,Arrays.copyOf(bytes,18000),3).result());var done=store.chunk(key,t,id,1,2,new byte[]{7},4);assertEquals(CheckedFileTransferStore.Result.COMPLETE,done.result());assertEquals(0,store.size(4));}@Test void rejectsOrderReplayMetadataAndWrongTarget()throws Exception{byte[] b={1};var s=new CheckedFileTransferStore();UUID t=UUID.randomUUID(),r=UUID.randomUUID(),id=UUID.randomUUID();var k=new CheckedFileTransferStore.Key(t,r,ClientFileCheckType.MODS,"a");var p=new CheckedFileTransferStore.Pending(k,"t","r",1,hash(b),1,100);s.create(p,1);assertEquals(CheckedFileTransferStore.Result.WRONG_TARGET,s.ready(k,UUID.randomUUID(),CheckedFileTransferControl.ready(id,1,hash(b)),2));assertEquals(CheckedFileTransferStore.Result.READY,s.ready(k,t,CheckedFileTransferControl.ready(id,1,hash(b)),2));assertEquals(CheckedFileTransferStore.Result.CHUNK_OUT_OF_ORDER,s.chunk(k,t,id,1,1,b,3).result());assertEquals(CheckedFileTransferStore.Result.NOT_FOUND,s.chunk(k,t,id,0,1,b,4).result());}}
